import React from 'react';
import { motion } from 'framer-motion';

const Hero = () => {
  return (
    <section className="relative overflow-hidden text-white min-h-screen">
      <div className="absolute inset-0 bg-gradient-to-r from-fuchsia-500 via-indigo-600 to-cyan-500 opacity-80 blur-3xl"></div>
      <div className="relative z-10 flex items-center justify-center min-h-screen px-6 py-24">
        <div className="max-w-6xl w-full grid grid-cols-1 lg:grid-cols-2 gap-8 items-center">
          <motion.div
            className="text-center lg:text-left"
            initial={{ opacity: 0, y: 40 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6 }}
          >
            <h1 className="text-4xl sm:text-5xl lg:text-6xl font-black mb-6 leading-tight drop-shadow-xl">
              Smart Healthcare for Smart Students
            </h1>
            <p className="text-lg sm:text-xl text-white/90 mb-8">
              No waiting. No paperwork. Just healthcare progress. Experience the future of campus health management with MediCampus.
            </p>
            <div className="flex flex-col sm:flex-row gap-4 justify-center lg:justify-start">
              <motion.button
                className="bg-yellow-400 text-black px-8 py-3 rounded-full font-bold shadow-xl hover:scale-105 hover:shadow-yellow-300/50 transition duration-300"
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.97 }}
              >
                Book Appointment
              </motion.button>
              <motion.button
                className="bg-gradient-to-r from-indigo-500 via-violet-500 to-fuchsia-500 text-white px-8 py-3 rounded-full font-bold shadow-xl hover:scale-105 transition duration-300"
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.97 }}
              >
                View Queue
              </motion.button>
            </div>
            <p className="mt-6 text-sm text-white/80">
              ⚡ Verified by campus clinics, connected to your student ID.
            </p>
          </motion.div>
          <motion.div
            className="flex justify-center"
            initial={{ opacity: 0, x: 50 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.8, delay: 0.2 }}
          >
            <div className="bg-white/10 border border-white/20 rounded-3xl p-8 w-[340px] h-[340px] flex items-center justify-center relative">
              <div className="absolute inset-0 bg-gradient-to-r from-cyan-300/30 via-indigo-300/20 to-fuchsia-300/30 rounded-3xl blur-xl animate-pulse"></div>
              <div className="relative w-72 h-72 rounded-2xl bg-slate-900/60 border border-white/25 grid place-items-center shadow-[0_30px_60px_rgba(0,0,0,0.35)]">
                <div className="text-center">
                  <div className="text-7xl">🩺</div>
                  <p className="mt-3 text-white/95 font-semibold">Live Health Dashboard</p>
                </div>
              </div>
            </div>
          </motion.div>
        </div>
      </div>
      <div className="absolute bottom-0 left-0 w-full h-24 bg-gradient-to-t from-white/20 via-transparent to-transparent"></div>
    </section>
  );
};

export default Hero;
